func prObservationEffect(project store.Project, task store.Task, current store.PRObservation, failures []failedCheck, previous store.PRObservation, hasPrevious bool) store.PRObservationEffect {
	effect := store.PRObservationEffect{}
	newHead := !hasPrevious || previous.HeadSHA != current.HeadSHA
	previousChecks := decodeChecks(previous.Checks)
	checks := decodeChecks(current.Checks)
	addNotice := func(kind, summary string, data any) {
		effect.Notices = append(effect.Notices, store.Notice{ProjectID: project.ID, TaskID: task.ID, Kind: kind, Summary: summary, DataJSON: marshalJSON(data), CreatedAt: current.ObservedAt})
	}
	switch current.State {
	case "MERGED":
		if !hasPrevious || previous.State != "MERGED" {
			addNotice("pr_merged", task.Title+": pull request merged", map[string]any{"url": current.PRURL, "head_sha": current.HeadSHA, "merge_commit": current.MergeCommit})
		}
		effect.TransitionTo = store.StateMerged
		effect.TransitionNote = "Pull request merged at " + current.MergeCommit
		effect.MergedRef = current.MergeCommit
	case "CLOSED":
		if !hasPrevious || previous.State != "CLOSED" {
			addNotice("pr_closed", task.Title+": pull request closed without merging", map[string]any{"url": current.PRURL, "head_sha": current.HeadSHA})
		}
	case "OPEN":
		// One Notice when the first check of a run fails, and one update when the
		// run settles with a failure set the last Notice did not name; failures
		// that pile up while the run is still going stay quiet.
		noticed := previousChecks.Noticed
		if newHead {
			noticed = nil
		}
		if len(failures) > 0 && (len(noticed) == 0 || !checks.Running && !sameFailures(noticed, failures)) {
			addNotice("pr_checks_failed", task.Title+": required checks failed: "+failedCheckNames(failures)+"; Posse queues the Worker fix (ci_fix_queued), or raises ci_fix_exhausted, and the Lead sends one only after ci_fix_exhausted", map[string]any{"url": current.PRURL, "head_sha": current.HeadSHA, "checks": failures})
		}
		if current.Review == "CHANGES_REQUESTED" && (newHead || previous.Review != "CHANGES_REQUESTED") {
			addNotice("pr_changes_requested", task.Title+": review requests changes", map[string]any{"url": current.PRURL, "head_sha": current.HeadSHA, "review": current.Review})
		}
		if (current.Mergeable == "CONFLICTING" || current.Mergeable == "BEHIND") && (newHead || previous.Mergeable != current.Mergeable) {
			summary := task.Title + ": pull request conflicts with the Task's frozen target branch"
			if current.Mergeable == "BEHIND" {
				summary = task.Title + ": pull request is behind its target under strict branch protection"
			}
			addNotice("pr_conflict", summary, map[string]any{"url": current.PRURL, "head_sha": current.HeadSHA})
		}
		// A head pushed after the gate, outside `posse publish`, is never merge-ready.
		if task.GatedSHA != "" && current.HeadSHA != task.GatedSHA {
			if newHead {
				addNotice("head_discontinuity", headDiscontinuityPRSummary(project, task, current), map[string]any{"url": current.PRURL, "gated_head": task.GatedSHA, "pr_head": current.HeadSHA})
			}
			break
		}
		ready := checks.State == "SUCCESS" && current.Review != "CHANGES_REQUESTED" && current.Review != "REVIEW_REQUIRED" && current.Mergeable == "MERGEABLE"
		if ready && !checks.MergeRequested && (task.State == store.StateDone || task.State == store.StateMerging) {
			addNotice("merge_ready", task.Title+": pull request checks and reviews are ready to merge head "+shortSHA(current.HeadSHA), map[string]any{"url": current.PRURL, "head_sha": current.HeadSHA})
		}
	}
	return effect
}

func headDiscontinuityPRSummary(project store.Project, task store.Task, current store.PRObservation) string {
	summary := fmt.Sprintf("%s: pull request head %s is not the gated head %s; Posse withholds merge_ready and `posse merge --execute` refuses. Restore %s on the request branch, or have the Worker adopt %s (reset the Task branch to it, publish and signal done) so Posse gates it. Rewrite published history only with `posse publish --rewrite --user-approved \"<User's words>\" \"<summary>\"`, which re-gates the new head", task.Title, current.HeadSHA, task.GatedSHA, task.GatedSHA, current.HeadSHA)
	if project.IsWorkspace() {
		summary += "; it supports single-repository Tasks only, so a workspace Member republishes a descendant of the gated head"
	}
	return summary + "."
}

