func acquireTaskBranchAuthorLock(ctx context.Context, worktree, branch string) (*os.File, error) {
	commonDir, err := repositoryCommonDir(ctx, worktree)
	if err != nil {
		return nil, fmt.Errorf("resolve branch author lock directory: %w", err)
	}
